contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(address account, uint256 id) public {
        require(account != address(0));
        bool zeroReverted;
        c.balanceOf(address(0), id); bool __rev0 = __ESBMC_reverted(); if (__rev0) { zeroReverted = true; } else { zeroReverted = false; }
        bool acctReverted;
        c.balanceOf(account, id); bool __rev1 = __ESBMC_reverted(); if (__rev1) { acctReverted = true; } else { acctReverted = false; }
        uint256 selfBal;
        bool selfReverted;
        c.balanceOf(address(this), id); bool __rev2 = __ESBMC_reverted(); if (__rev2) { selfReverted = true; } else { selfBal = c.balanceOf(address(this), id); selfReverted = false; }
        assert(zeroReverted && !acctReverted && !selfReverted && selfBal == 0);
    }
}

