// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(address account, uint256 id) internal {
        vm.assume(account != address(0));
        bool zeroReverted;
        try c.balanceOf(address(0), id) { zeroReverted = false; } catch { zeroReverted = true; }
        bool acctReverted;
        try c.balanceOf(account, id) { acctReverted = false; } catch { acctReverted = true; }
        uint256 selfBal;
        bool selfReverted;
        try c.balanceOf(address(this), id) { selfBal = c.balanceOf(address(this), id); selfReverted = false; } catch { selfReverted = true; }
        assertTrue(zeroReverted && !acctReverted && !selfReverted && selfBal == 0);
    }

    function testFuzz_run(address account, uint256 id) public {
        vm.assume(account.code.length == 0 && uint160(account) > 0xffff && account != address(this) && account != address(c) && account != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && account != 0x000000000000000000636F6e736F6c652e6c6f67 && account != 0x4e59b44847b379578588920cA78FbF26c0B4956C && account != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(account, id);
    }

    receive() external payable {}
}
